// Get resume analysis safely
const resumeData = $input.first().json.output || {};
const candidateSkills = (resumeData.skills || []).map(s => s.toLowerCase());
const candidateYears = resumeData.experience_years || 0;

// Get jobs safely
const jobs = $('Fetch Job Listings').first().json.jobs || [];

const rankedJobs = jobs.map(job => {
  let score = 0;

  // ---- SKILL MATCHING (70 pts) ----
  const jobSkills = (job.required_skills || []).map(s => s.toLowerCase());

  let matchingSkills = [];
  if (jobSkills.length > 0) {
    matchingSkills = jobSkills.filter(skill =>
      candidateSkills.some(cs => cs.includes(skill) || skill.includes(cs))
    );

    const skillScore = (matchingSkills.length / jobSkills.length) * 70;
    score += skillScore;
  }

  // ---- EXPERIENCE MATCHING (30 pts) ----
  let expText = job.experience_required || "";
  let numbers = expText.match(/\d+/g);

  if (numbers) {
    const minExp = parseInt(numbers[0]);
    const maxExp = numbers.length > 1 ? parseInt(numbers[1]) : minExp + 2;

    if (candidateYears >= minExp && candidateYears <= maxExp + 1) {
      score += 30;
    } else if (candidateYears >= minExp - 1) {
      score += 15;
    }
  }

  // ---- FINAL OBJECT ----
  return {
    ...job,
    match_score: Math.round(score),
    matching_skills: matchingSkills,
    missing_skills: jobSkills.filter(s => !matchingSkills.includes(s))
  };
});

// ---- SORT + TOP MATCHES ----
const topMatches = rankedJobs
  .sort((a, b) => b.match_score - a.match_score)
  .slice(0, 3);

// ---- FINAL OUTPUT ----
return [{
  json: {
    candidate_name: $('Resume Upload Webhook').first().json.body.candidateName || "Unknown",
    candidate_email: $('Resume Upload Webhook').first().json.body.email || "N/A",
    resume_summary: resumeData.summary || "",
    top_matches: topMatches,
    total_jobs_analyzed: jobs.length
  }
}];

