(() => {

const candidate = $json;

const getScoreColor = (score) => {
  if (score >= 75) return "#16a34a";   // green
  if (score >= 50) return "#f59e0b";   // orange
  return "#dc2626";                    // red
};

const jobsHTML = (candidate.top_matches || []).map((job, i) => {
  const color = getScoreColor(job.match_score || 0);

  return `
  <div style="margin-bottom:20px;padding:20px;border-radius:10px;border:1px solid #e5e7eb;background:#ffffff;">

    <h3 style="margin:0 0 10px 0;">
      ${i + 1}. ${job.title || "Untitled Role"}
    </h3>

    <p><strong>🏢 Company:</strong> ${job.company_name || "N/A"}</p>
    <p><strong>📍 Location:</strong> ${job.candidate_required_location || "Remote"}</p>
    <p><strong>💰 Salary:</strong> ${job.salary || "Not disclosed"}</p>

    <p>
      <strong>🎯 Match Score:</strong> 
      <span style="color:${color}; font-weight:bold;">
        ${job.match_score || 0}%
      </span>
    </p>

    <p><strong>✅ Matching Skills:</strong> 
      ${(job.matching_skills && job.matching_skills.length)
        ? job.matching_skills.join(", ")
        : "None"}
    </p>

    <p><strong>⚠️ Missing Skills:</strong> 
      ${(job.missing_skills && job.missing_skills.length)
        ? job.missing_skills.join(", ")
        : "Not specified"}
    </p>

    <a href="${job.url}" target="_blank"
       style="display:inline-block;margin-top:10px;padding:10px 15px;background:#0073b1;color:#fff;text-decoration:none;border-radius:6px;">
       🔗 View Job
    </a>

  </div>
  `;
}).join("");

// FINAL TEMPLATE
return `
<div style="font-family:Arial, sans-serif; max-width:700px; margin:auto; background:#f9fafb; padding:25px; border-radius:10px;">

  <h2 style="text-align:center; color:#111827;">
    🚀 Your Job Matches Report
  </h2>

  <p><strong>👤 Name:</strong> ${candidate.candidate_name || "Candidate"}</p>
  <p><strong>📧 Email:</strong> ${candidate.candidate_email}</p>

  <div style="margin:20px 0; padding:15px; background:#ffffff; border-radius:8px;">
    <h3>🧠 Resume Summary</h3>
    <p>${candidate.resume_summary || "No summary available"}</p>
  </div>

  <h3>🎯 Top Job Matches</h3>

  ${jobsHTML || "<p>No matching jobs found.</p>"}

  <div style="margin-top:30px; font-size:12px; color:#6b7280; text-align:center;">
    🔍 Jobs analyzed: ${candidate.total_jobs_analyzed || 0}
  </div>

</div>
`;

})()
}}
